<template><section><h1>My tasks</h1><div class="summary"><span>{{tasks.filter(t=>!t.completed).length}} open</span><span>{{tasks.filter(t=>t.completed).length}} done</span></div><form @submit.prevent="add"><input v-model="title" placeholder="What needs doing?" minlength="2" required/><button>Add task</button></form><p v-if="!tasks.length">You are all caught up.</p><ul><li v-for="task in tasks" :key="task.id"><span :class="{done:task.completed}">{{task.title}}</span><button @click="complete(task.id)" :disabled="task.completed">{{task.completed?'Done':'Complete'}}</button></li></ul></section></template><script setup lang="ts">import {ref} from 'vue';type Task={id:string;title:string;completed:boolean};const tasks=ref<Task[]>([]);const title=ref('');function add(){tasks.value.unshift({id:crypto.randomUUID(),title:title.value,completed:false});title.value=''}function complete(id:string){const t=tasks.value.find(x=>x.id===id);if(t)t.completed=true}</script><style>.summary{display:flex;gap:12px;margin-bottom:20px}.summary span,li{background:white;padding:14px;border-radius:10px}form{display:flex;gap:8px}li{list-style:none;margin:8px 0;display:flex;justify-content:space-between}.done{text-decoration:line-through}</style>